function asArray(item) {
  const json = item.json;
  if (Array.isArray(json)) return json;
  if (json && json.data && Array.isArray(json.data.workspaceMembers)) return json.data.workspaceMembers;
  if (json && Array.isArray(json.workspaceMembers)) return json.workspaceMembers;
  return [];
}

const matches = $input.all().flatMap(asArray);
if (matches.length === 0) return [{ json: { found: false } }];

const rep = matches[0];
return [{
  json: {
    found: true,
    rep: {
      id: rep.id,
      name: rep.name || rep.email,
      sipExtension: rep.sipExtension || null,
      dialerStatus: rep.dialerStatus || 'Offline',
    },
  },
}];
